[{"order":1,"type":"heading","text":"Contract Upgradeability Patterns: Proxy, Diamond (ERC-2535), and UUPS"},{"order":2,"type":"paragraph","text":"Smart contracts on EVM-compatible blockchains are immutable by default. Once deployed, their bytecode cannot be changed. However, business logic evolves, bugs are discovered, and features need updates. Contract upgradeability patterns solve this challenge by separating storage from logic, allowing pointers to redirect execution to new implementations."},{"order":3,"type":"subheading","text":"1. The Transparent Proxy Pattern"},{"order":4,"type":"paragraph","text":"The Transparent Proxy pattern uses a proxy contract that delegates all calls to a logic contract via `delegatecall`. The proxy manages ownership and upgrade administration. If the admin calls the proxy, the proxy handles the call locally (e.g., upgrading the implementation). If any other user calls the proxy, it delegates the call to the logic contract. This prevents function selector clashes between admin functions and user functions."},{"order":5,"type":"code","text":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract SimpleProxy {
    bytes32 private constant IMPLEMENTATION_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
    bytes32 private constant ADMIN_SLOT = 0xb53127684a568b3173ae13b9f8a6016e243e63b6e8ee1178d6a717850b5d6103;

    constructor(address _implementation) {
        _setAdmin(msg.sender);
        _setImplementation(_implementation);
    }

    modifier ifAdmin() {
        if (msg.sender == _getAdmin()) {
            _;
        } else {
            _fallback();
        }
    }

    function changeAdmin(address newAdmin) external ifAdmin {
        _setAdmin(newAdmin);
    }

    function upgradeTo(address newImplementation) external ifAdmin {
        _setImplementation(newImplementation);
    }

    function _getAdmin() internal view returns (address adm) {
        bytes32 slot = ADMIN_SLOT;
        assembly { adm := sload(slot) }
    }

    function _setAdmin(address newAdmin) internal {
        bytes32 slot = ADMIN_SLOT;
        assembly { sstore(slot, newAdmin) }
    }

    function _getImplementation() internal view returns (address impl) {
        bytes32 slot = IMPLEMENTATION_SLOT;
        assembly { impl := sload(slot) }
    }

    function _setImplementation(address newImplementation) internal {
        bytes32 slot = IMPLEMENTATION_SLOT;
        assembly { sstore(slot, newImplementation) }
    }

    function _fallback() internal {
        address impl = _getImplementation();
        assembly {
            calldatacopy(0, 0, calldatasize())
            let result := delegatecall(gas(), impl, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch result
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }

    fallback() external payable {
        _fallback();
    }

    receive() external payable {
        _fallback();
    }
}"},{"order":6,"type":"subheading","text":"2. Universal Upgradeable Proxy Standard (UUPS - ERC-1822)"},{"order":7,"type":"paragraph","text":"The UUPS pattern moves the upgrade logic directly into the implementation contract rather than the proxy contract. This reduces gas costs on deployment and removes proxy administrative overhead. However, it requires every implementation to correctly inherit and expose an upgrade function to prevent permanently locking the contract."},{"order":8,"type":"code","text":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

abstract contract UUPSUpgradeable {
    bytes32 private constant IMPLEMENTATION_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    event Upgraded(address indexed implementation);

    function upgradeTo(address newImplementation) external virtual {
        _authorizeUpgrade(newImplementation);
        _setImplementation(newImplementation);
        emit Upgraded(newImplementation);
    }

    function _authorizeUpgrade(address newImplementation) internal virtual;

    function _setImplementation(address newImplementation) internal {
        assembly {
            sstore(IMPLEMENTATION_SLOT, newImplementation)
        }
    }
}"},{"order":9,"type":"subheading","text":"3. Diamond Standard (ERC-2535)"},{"order":10,"type":"paragraph","text":"The Diamond pattern allows building modular smart contract systems that can be upgraded instantly without the 24KB contract size limit. A diamond is a proxy contract that routes function calls to multiple implementation contracts, known as facets. Facets share the diamond's storage layout using AppStorage or structured storage slots."},{"order":11,"type":"bullet_point","text":"Diamond Proxy: Holds storage and routes calls using 4-byte function selectors mapped to facet addresses."},{"order":12,"type":"bullet_point","text":"Facets: Stateless or state-aware modules containing specific sets of external functions."},{"order":13,"type":"bullet_point","text":"DiamondCut Facet: Manages adding, replacing, or removing function selectors and facets."},{"order":14,"type":"subheading","text":"Comparative Summary of Patterns"},{"order":15,"type":"bullet_point","text":"Transparent Proxy: Safest for beginners, upgrade logic in proxy, higher deployment gas."},{"order":16,"type":"bullet_point","text":"UUPS: Gas efficient, upgrade logic in implementation, risk of bricking if upgrade function is omitted."},{"order":17,"type":"bullet_point","text":"Diamond (ERC-2535): Unlimited contract size, highly modular, complex architecture and tooling required."}]
